import sys

def solve(s):
    target = "abcdefghijklmnopqrstuvwxyz"
    t_idx = 0
    s = list(s)

    for i in range(len(s)):
        if t_idx < len(target) and s[i] <= target[t_idx]:
            s[i] = target[t_idx]
            t_idx += 1

    if t_idx == len(target):
        return ''.join(s)
    else:
        return '-1'

input = sys.stdin.read
