import sys
input = sys.stdin.read
data = input().split()

s = data[0]

result = ""
current = ord('a')
for char in s:
    if ord(char) <= current:
        result += chr(current)
        current += 1
        if current > ord('z'):
            break

if len(result) < 26:
    print(-1)
else:
    print(result)

